   card('عاين', 'رأى بنفسه ليشهد', 'عاين المفتّش الرصيف بنفسه، والمعاينة شهادة، وتطلب ريم أن تعاين المدخل، وتعاين نورة الصفحة قبل الطبع.'),
   card('شاهد', 'حضر الشيء كلّه من أوّله إلى آخره', 'شاهدت الاجتماع كلّه، وشاهد غير رأى، ولم تشاهد ريم الجلسة لأنّها تأخّرت، ومن شاهد يُسأل عن الدقائق الأولى.'),
   card('ذكر', 'أورد الشيء في كلامه بلا قوّة زائدة', 'ذكر رئيس المجلس أنّ الإغلاق مؤقّت، وذكر يروي ولا يحكم، وتكتب ريم ذكر بدل أكّد، وذكرت المديرة الرقم مرّة.'),
   card('صرّح', 'قال علنًا بصفته الرسمية', 'صرّح رئيس المجلس باسم المجلس، ويصرّح من يتكلّم بصفته، وأبو فيصل يقول ولا يصرّح، وتنقل ريم ما صرّح به حرفيًّا.'),
   card('أقرّ', 'قبِل صحّة الشيء حين سُئل عنه', 'أقرّ الموظّف بأنّ الرصيف اكتمل منذ سنة، وأقرّ يروي واعترف يحكم، وأقرّت ريم بأنّها تأخّرت، ومن أقرّ لم يُدَن.'),
   card('اعترف', 'أقرّ بما يُعدّ عليه ذنبًا', 'في اعترف صوت المحكمة، ولا يُكتب اعترف عمّن أجاب عن سؤال، وصحّح عمر اعترفت إلى أقرّت، ويبحث القارئ بعد اعترف عن الجريمة.'),
