   cloze('أكمل السلّم', '___ بطرف العين مصادفة، و___ أطال النظر مفكّرًا، و___ ثبّت النظر بحدّة.', ['لمح', 'تأمّل', 'حدّق'], ['عاين', 'رمق', 'شاهد']),
   cloze('أكمل العمودين', 'قال وذكر وأقرّ ___، وأكّد واعترف ونفى ___ فلا تُكتب إلّا ___.', ['تروي', 'تحكم', 'بوقوعها'], ['تصف', 'تسأل', 'بالرأي']),
